action.command:
cd /tmp && rm -f cj.txt && TOKEN=$(curl -s -c cj.txt -m 20 http://127.0.0.1:3000/ | grep -o 'name="csrf-token" content="[^"]*"' | head -1 | sed 's/.*content="//;s/"//'); echo "TOKEN_LEN=${#TOKEN}"; curl -s -b cj.txt -c cj.txt -m 30 -X POST http://127.0.0.1:3000/api/v1/signin -H 'Content-Type: application/json' -H "X-CSRF-Token: $TOKEN" -d '{"username":"admin@example.com","password":"test"}' -w "
HTTP %{http_code}
" -o /tmp/signin.json; echo "---BODY---"; head -c 800 /tmp/signin.json; echo; echo "---AUTH CHECK---"; curl -s -b cj.txt -m 20 http://127.0.0.1:3000/api/v1/users/me -w "
HTTP %{http_code}
" | head -c 500
